  "sources": {
    "pwm_gen.v": "module pwm_gen #(\n  parameter integer WIDTH = 8\n)(\n  input  wire             clk,\n  input  wire             rst_n,\n  input  wire             en,\n  input  wire [WIDTH-1:0] duty,\n  output reg              pwm_out\n);\n\n  reg [WIDTH-1:0] cnt;\n\n  always @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      cnt     <= {WIDTH{1'b0}};\n      pwm_out <= 1'b0;\n    end else if (en) begin\n      cnt     <= cnt + 1'b1;\n      pwm_out <= (cnt < duty);\n    end else begin\n      cnt     <= {WIDTH{1'b0}};\n      pwm_out <= 1'b0;\n    end\n  end\n\nendmodule\n",
    "pwm_gen.v@v1": "module pwm_gen #(\n  parameter integer WIDTH = 8\n)(\n  input  wire             clk,\n  input  wire             rst_n,\n  input  wire             en,\n  input  wire [WIDTH-1:0] duty,\n  output reg              pwm_out\n);\n\n  reg [WIDTH-1:0] cnt;\n\n  always @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      cnt     <= {WIDTH{1'b0}};\n      pwm_out <= 1'b0;\n    end else if (en) begin\n      cnt     <= cnt + 1'b1;\n      pwm_out <= (cnt > duty);\n    end else begin\n      cnt     <= {WIDTH{1'b0}};\n      pwm_out <= 1'b0;\n    end\n  end\n\nendmodule\n",
    "pwm_gen_tb.v": "`timescale 1ns/1ps\n\nmodule pwm_gen_tb;\n\n  reg        clk   = 1'b0;\n  reg        rst_n = 1'b0;\n  reg        en    = 1'b0;\n  reg  [7:0] duty  = 8'd0;\n  wire       pwm_out;\n\n  integer high = 0;\n  integer i;\n\n  pwm_gen #(.WIDTH(8)) dut (\n    .clk(clk), .rst_n(rst_n), .en(en), .duty(duty), .pwm_out(pwm_out)\n  );\n\n  always #5 clk = ~clk;\n\n  initial begin\n    #20 rst_n = 1'b1;\n    duty = 8'd64;\n    en   = 1'b1;\n\n    @(posedge clk);\n    for (i = 0; i < 256; i = i + 1) begin\n      @(posedge clk);\n      if (pwm_out) high = high + 1;\n    end\n\n    if (high < 60 || high > 68) begin\n      $display(\"FAIL duty mismatch: high=%0d expected ~64\", high);\n      $finish;\n    end\n\n    $display(\"PASS pwm duty=64/256 measured high=%0d\", high);\n    $finish;\n  end\n\nendmodule\n",
    "pwm_gen.xdc": "create_clock -period 10.000 -name clk [get_ports clk]\n\n# smoke 场景：无引脚约束，显式降级 write_bitstream 的 NSTD-1/UCIO-1 DRC\nset_property SEVERITY {Warning} [get_drc_checks NSTD-1]\nset_property SEVERITY {Warning} [get_drc_checks UCIO-1]\n"
  }
